<?php require_once 'db.php'; require_admin(); $page_title='Admin report'; $rows=db()->query("SELECT status,COUNT(*) AS total,SUM(amount) AS value_total FROM bookings GROUP BY status")->fetchAll(); include 'header.php'; ?>
<section class="section"><div class="eyebrow">REPORTING</div><h1 style="font-size:3rem">Bookings report.</h1><div class="panel table-wrap"><table><thead><tr><th>Status</th><th>Count</th><th>Total value (demo)</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= h($r['status']) ?></td><td><?= (int)$r['total'] ?></td><td>₹<?= number_format((float)$r['value_total'],2) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="3">No bookings recorded yet.</td></tr><?php endif; ?></tbody></table><p class="muted">This report reflects only local demo data.</p><button class="btn" onclick="window.print()">Print report</button></div></section><?php include 'footer.php'; ?>